/** Walk to the table at `parts`, creating the tables on the way. */
function descend(root, parts, path) {
  let current = root
  let currentPath = [...path]

  for (const part of parts) {
    const held = current.value.get(part)

    if (held === undefined) {
      // Create a new table if nothing is there
      const fresh = table()
      current.value.set(part, fresh)
      current = fresh
      currentPath.push(part)
    } else if (held.type === 'table') {
      // Descend into an existing table
      current = held
      currentPath.push(part)
    } else if (held.type === 'tables') {
      // Descend into the last element of an array of tables
      current = held.value[held.value.length - 1]
      currentPath.push(part)
    } else {
      // Error: something other than a table or array of tables
      throw new ConfError(`${currentPath.concat(part).join('.')} is not a table`)
    }
  }

  return current
}

